NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
// Search for the product by exact ID
let row = db.prepare('SELECT * FROM products WHERE product_id=?').get('PROD-B98D14');
console.log('Exact match:', row);
// Also try a LIKE search
let rows = db.prepare(\"SELECT * FROM products WHERE product_id LIKE '%B98D14%'\").all();
console.log('LIKE match:', rows);
// Also search by name
let rows2 = db.prepare(\"SELECT * FROM products WHERE name LIKE '%B98D14%'\").all();
console.log('Name match:', rows2);
"

